const WORDS = [["anthropic","claude"],["claude","claude"],["chatgpt","openai"],["openai","openai"],["codex","openai"],["gemini","gemini"],["googleapis","gemini"],["google","gemini"],["grok","grok"],["x.ai","grok"],["xai","grok"],["mistral","mistral"],["deepseek","deepseek"],["qwen","qwen"],["dashscope","qwen"],["alibaba","qwen"],["kimi","kimi"],["moonshot","moonshot"],["bigmodel","zhipu"],["zhipu","zhipu"],["z.ai","zai"],["glm","zhipu"],["minimax","minimax"],["groq","groq"],["ollama","ollama"],["openrouter","openrouter"],["together","together"],["fireworks","fireworks"],["cerebras","cerebras"],["perplexity","perplexity"],["cohere","cohere"],["azure","azure"],["bedrock","bedrock"],["copilot","githubcopilot"],["huggingface","huggingface"],["nvidia","nvidia"],["poe","poe"],["digitalocean","digitalocean"],["venice","venice"],["lmstudio","lmstudio"],["vllm","vllm"],["deepinfra","deepinfra"],["novita","novita"],["sambanova","sambanova"],["siliconflow","siliconcloud"],["volces","volcengine"],["doubao","doubao"],["stepfun","stepfun"],["mimo","xiaomimimo"],["hunyuan","hunyuan"],["cloudflare","cloudflare"],["nebius","nebius"],["antigravity","antigravity"],["llama","meta"]];

export function providerLogoName(id, name = "", url = "") {
  const pid = String(id || "").toLowerCase();
  if (EXACT[pid]) return EXACT[pid];
  const base = pid.replace(/(-\d+|-(cn|eu|us|intl|global|coding-plan|token-plan))+$/, "");
  if (EXACT[base]) return EXACT[base];
  const hay = `${pid} ${String(name).toLowerCase()} ${String(url).toLowerCase()}`;
  for (const [w, n] of WORDS) if (hay.includes(w)) return n;
  return "";
}

export function providerLogo(id, name, url) {
  const n = providerLogoName(id, name, url);
  return n ? SVG[n] : "";
}
